parameters.jsCode:
const body = $json.body || $json;
const project = body.data || body;

return {
  json: {
    event: body.event || 'PROJECT_UPDATED',
    projectId: project.id || 'PRJ-0000',
    title: project.title || 'Website Project',
    status: project.status || 'In Development',
    clientEmail: project.clientEmail || project.client?.email || 'N/A',
    clientName: project.clientName || project.client?.name || 'Client',
    clientPhone: project.clientPhone || project.client?.phone || 'N/A',
    deadline: project.deadline ? new Date(project.deadline).toLocaleDateString('en-IN') : 'TBD',
    updatedAt: new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })
  }
};

